14	namespace DSRAutoMailScheduler
15	{
16	    class Program
17	    {
18	        private static readonly Logger Logger = LogManager.GetCurrentClassLogger();
19	        private static SmtpSettings _smtpSettings;
20	        private static Dictionary<string, string> _serverDict;
21	        private static string ReportFolder;
22	        private static string fileName;
23	        private static string savePath;
24	
