40	        public class RowPointers
41	        {
42	            public int ClientRow = 1;   // Sheet 1: OCR_AI ENABLED CLIENT LIST
43	            public int JobRow = 1;   // Sheet 2: OCR_AI TOTAL JOB COUNT
44	            public int FormatRow = 1;   // Sheet 3: OCR_AI Total Format details
45	        }
46	
47	        static async Task Main(string[] args)
48	        {
49	            try
50	            {
51	                RowPointers rows = new RowPointers();
52	
53	                var builder = new ConfigurationBuilder()
54	                    .SetBasePath(AppContext.BaseDirectory)
55	                    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);
56	
57	                IConfiguration config = builder.Build();
58	                _smtpSettings = config.GetSection("SmtpSettings").Get<SmtpSettings>();
59	                _serverDict = config.GetSection("server_ip_list").Get<Dictionary<string, string>>();
60	                ReportFolder = config.GetSection("ReportSettings:ReportFolder").Value;
61	
62	                if (!Directory.Exists(ReportFolder))
63	                    Directory.CreateDirectory(ReportFolder);
64	
65	                using var workbook = new XLWorkbook();
66	                {
67	                    // ── Sheet 1: OCR_AI Enabled Client List ──────────────────
68	                    var wsClient = workbook.Worksheets.Add("OCR_AI ENABLED CLIENT LIST");
69	
70	                    // ── Sheet 2: OCR_AI Total Job Count ──────────────────────
71	                    var wsJob = workbook.Worksheets.Add("OCR_AI TOTAL JOB COUNT");
72	
73	                    // ── Sheet 3: OCR_AI Total Format Details ─────────────────
74	                    var wsFormat = workbook.Worksheets.Add("OCR_AI Total Format details");
75	
76	                    foreach (var kvp in _serverDict)
77	                    {
78	                        string serverName = kvp.Key;
79	                        string serverIp = kvp.Value;
80	
81	                        Logger.Info("Getting OCR data for server {0} ({1})", serverName, serverIp);
82	
83	                        // Admin DB connection — same pattern as IRN
84	                        string connString = $"Server={serverIp};database=ImpexLogin;uid=sa;pwd=SA,123;TrustServerCertificate=True;";
85	
86	                        await GetOcrDataList(connString, wsClient, wsJob, wsFormat, serverName, rows);
87	                    }
88	
89	                    // ── Style all three sheets ────────────────────────────────
90	                    StyleSheet(wsClient, "OCR AI ENABLED CLIENT LIST", rows.ClientRow - 1, 7);
91	                    StyleSheet(wsJob, "OCR AI TOTAL JOB COUNT", rows.JobRow - 1, -1); // dynamic cols
92	                    StyleSheet(wsFormat, "OCR AI TOTAL FORMAT DETAILS", rows.FormatRow - 1, 15);
93	
94	                    fileName = $"OCR_AI_Report_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
95	                    savePath = Path.Combine(ReportFolder, fileName);
96	                    workbook.SaveAs(savePath);
97	                    Logger.Info("Excel saved: {0}", savePath);
98	                }
99	
100	                await SendEmailWithAttachment(savePath);
101	
102	                if (File.Exists(savePath))
103	                {
104	                    File.Delete(savePath);
105	                    Logger.Info("Deleted report after email: {0}", fileName);
106	                }
107	            }
108	            catch (Exception ex)
109	            {
110	                Logger.Error(ex, "Error in Main");
111	            }
112	        }
113	
114	        // ─────────────────────────────────────────────────────────────────────
115	        // Main data fetch per server
116	        // ─────────────────────────────────────────────────────────────────────
117	        private static async Task GetOcrDataList(
118	            string connString,
119	            IXLWorksheet wsClient,
120	            IXLWorksheet wsJob,
121	            IXLWorksheet wsFormat,
122	            string serverName,
123	            RowPointers rows)
124	        {
125	            await Task.Run(() =>
126	            {
127	                // ── Step 1: Call admin SP to get enabled OCR companies ────────
128	                DataSet adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
129	
130	                if (adminData == null || adminData.Tables.Count < 2)
131	                {
132	                    Logger.Warn("Server {0}: No OCR data returned from admin SP", serverName);
133	                    return;
134	                }
135	
136	                DataTable clientList = adminData.Tables[0]; // → Sheet 1
137	                DataTable serverList = adminData.Tables[1]; // connection details
138	
139	                Logger.Info("Server {0}: OCR Clients={1}, Databases={2}",
140	                    serverName, clientList.Rows.Count, serverList.Rows.Count);
141	
142	                // ── Sheet 1: Append enabled client list ───────────────────────
143	                AppendDataTable(wsClient, clientList, ref rows.ClientRow);
144	
145	                // ── Step 2: For each client DB, call client SP ────────────────
146	                foreach (DataRow server in serverList.Rows)
147	                {
148	                    string workingPeriod = server["WORKING_PERIOD"].ToString();
149	                    string companyLicense = server["COMPANY_LICENSE"].ToString();
150	                    string companyName = server["COMPANY_NAME"].ToString();
151	                    string clientConn = server["CON_STRING"].ToString();
152	
153	                    string enabledDate = ParseDateToYMD(server["ENABLED_ON"].ToString());
154	                    string disabledDate = string.IsNullOrWhiteSpace(server["DISABLED_ON"].ToString())
155	                        ? ""
156	                        : ParseDateToYMD(server["DISABLED_ON"].ToString());
157	
158	                    // ── Sheet 2: JOB_COUNT ────────────────────────────────────
159	                    DataTable jobData = GetClientData(
160	                        clientConn, "JOB_COUNT",
161	                        serverName, workingPeriod, companyLicense,
162	                        companyName, enabledDate, disabledDate);
163	
164	                    Logger.Info("Server {0}, Company {1}: JOB rows={2}",
165	                        serverName, companyLicense, jobData.Rows.Count);
166	
167	                    AppendDataTable(wsJob, jobData, ref rows.JobRow);
168	
169	                    // ── Sheet 3: FORMAT_COUNT ─────────────────────────────────
170	                    DataTable formatData = GetClientData(
171	                        clientConn, "FORMAT_COUNT",
172	                        serverName, workingPeriod, companyLicense,
173	                        companyName, enabledDate, disabledDate);
174	
175	                    Logger.Info("Server {0}, Company {1}: FORMAT rows={2}",
176	                        serverName, companyLicense, formatData.Rows.Count);
177	
178	                    AppendDataTable(wsFormat, formatData, ref rows.FormatRow);
179	                }
180	            });
181	        }
182	
183	        // ─────────────────────────────────────────────────────────────────────
184	        // Admin SP: OCR_AI_ENABLED_COUNT  (ImpexLogin DB)
185	        // ─────────────────────────────────────────────────────────────────────
186	        private static DataSet GetAdminData(string connString, string flag, string serverName)
187	        {
188	            using var con = new SqlConnection(connString);
189	            using var cmd = new SqlCommand("OCR_AI_ENABLED_COUNT", con)
190	            {
191	                CommandType = CommandType.StoredProcedure,
192	                CommandTimeout = 120
193	            };
194	
195	            cmd.Parameters.AddWithValue("@MFLAG", flag);
196	            cmd.Parameters.AddWithValue("@serverName", serverName);
197	
198	            var errorParam = new SqlParameter("@ERRORMSG", System.Data.SqlDbType.NVarChar, -1)
199	            {
200	                Direction = ParameterDirection.Output
201	            };
202	            cmd.Parameters.Add(errorParam);
203	
204	            var adapter = new SqlDataAdapter(cmd);
205	            var ds = new DataSet();
206	            adapter.Fill(ds);
207	
208	            string errorMsg = errorParam.Value?.ToString();
209	            if (!string.IsNullOrEmpty(errorMsg))
210	                Logger.Warn("Admin SP Error [{0}]: {1}", serverName, errorMsg);
211	
212	            return ds;
213	        }
214	
215	        // ─────────────────────────────────────────────────────────────────────
216	        // Client SP: OCR_AI_JOB_COUNT  (Client DB)
217	        // Used for both JOB_COUNT and FORMAT_COUNT flags
218	        // ─────────────────────────────────────────────────────────────────────
219	        private static DataTable GetClientData(
220	            string connStr,
221	            string flag,
222	            string serverName,
223	            string workingPeriod,
224	            string companyLicense,
225	            string companyName,
226	            string enabledDate,
227	            string disabledDate)
228	        {
229	            try
230	            {
231	                using var conn = new SqlConnection(connStr);
232	                using var cmd = new SqlCommand("OCR_AI_JOB_COUNT", conn)
233	                {
234	                    CommandType = CommandType.StoredProcedure,
235	                    CommandTimeout = 120
236	                };
237	
238	                cmd.Parameters.AddWithValue("@MFLAG", flag);
239	                cmd.Parameters.AddWithValue("@Server_name", serverName);
240	                cmd.Parameters.AddWithValue("@WORKING_PERIOD", workingPeriod);
241	                cmd.Parameters.AddWithValue("@COMPANY_LICENSE", companyLicense);
242	                cmd.Parameters.AddWithValue("@COMPANY_NAME", companyName);
243	                cmd.Parameters.AddWithValue("@ENABLED_DATE", enabledDate);
244	                cmd.Parameters.AddWithValue("@DISABLED_DATE", disabledDate);
245	
246	                var errorParam = new SqlParameter("@ERRORMSG", System.Data.SqlDbType.NVarChar, -1)
247	                {
248	                    Direction = ParameterDirection.Output
249	                };
250	                cmd.Parameters.Add(errorParam);
251	
252	                var adapter = new SqlDataAdapter(cmd);
253	                var ds = new DataSet();
254	                adapter.Fill(ds);
255	
256	                string errorMsg = errorParam.Value?.ToString();
257	                if (!string.IsNullOrEmpty(errorMsg))
258	                    Logger.Warn("Client SP Error [{0}][{1}][{2}]: {3}",
259	                        serverName, companyLicense, flag, errorMsg);
260	
261	                return ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
262	            }
263	            catch (Exception ex)
264	            {
265	                Logger.Error(ex, "GetClientData failed [{0}][{1}][{2}]",
266	                    serverName, companyLicense, flag);
267	                return new DataTable();
268	            }
269	        }
270	
271	        // ─────────────────────────────────────────────────────────────────────
272	        // Append DataTable rows to worksheet (with header on first call)
273	        // ─────────────────────────────────────────────────────────────────────
274	        private static void AppendDataTable(IXLWorksheet ws, DataTable table, ref int currentRow)
275	        {
276	            if (table == null || table.Rows.Count == 0) return;
277	
278	            // Write header only on first call (row 1)
279	            if (currentRow == 1)
280	            {
281	                for (int col = 0; col < table.Columns.Count; col++)
282	                {
283	                    var cell = ws.Cell(currentRow, col + 1);
284	                    cell.Value = table.Columns[col].ColumnName;
285	                    cell.Style.Font.Bold = true;
286	                    cell.Style.Fill.BackgroundColor = XLColor.DarkBlue;
287	                    cell.Style.Font.FontColor = XLColor.White;
288	                    cell.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
289	                }
290	                currentRow++;
291	            }
292	
293	            foreach (DataRow row in table.Rows)
294	            {
295	                for (int col = 0; col < table.Columns.Count; col++)
296	                {
297	                    ws.Cell(currentRow, col + 1).Value = row[col]?.ToString();
298	                }
299	
300	                // Alternate row color
301	                if (currentRow % 2 == 0)
302	                {
303	                    ws.Range(currentRow, 1, currentRow, table.Columns.Count)
304	                      .Style.Fill.BackgroundColor = XLColor.LightGray;
305	                }
306	
307	                currentRow++;
308	            }
309	        }
310	
311	        // ─────────────────────────────────────────────────────────────────────
312	        // Apply title, freeze, borders, auto-fit to a sheet
313	        // ─────────────────────────────────────────────────────────────────────
314	        private static void StyleSheet(IXLWorksheet ws, string title, int lastDataRow, int colCount)
315	        {
316	            try
317	            {
318	                // Insert title row at top
319	                ws.Row(1).InsertRowsAbove(1);
320	                int usedCols = colCount > 0 ? colCount : ws.LastColumnUsed()?.ColumnNumber() ?? 1;
321	
322	                var titleRange = ws.Range(1, 1, 1, usedCols);
323	                titleRange.Merge();
324	                titleRange.FirstCell().Value = title;
325	                titleRange.Style.Font.Bold = true;
326	                titleRange.Style.Font.FontSize = 14;
327	                titleRange.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
328	                titleRange.Style.Fill.BackgroundColor = XLColor.Navy;
329	                titleRange.Style.Font.FontColor = XLColor.White;
330	
331	                ws.SheetView.FreezeRows(2);
332	
333	                if (ws.RangeUsed() != null)
334	                {
335	                    ws.RangeUsed().Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
336	                    ws.RangeUsed().Style.Border.InsideBorder = XLBorderStyleValues.Thin;
337	                }
338	
339	                ws.Columns().AdjustToContents();
340	            }
341	            catch (Exception ex)
342	            {
343	                Logger.Warn("StyleSheet failed for {0}: {1}", ws.Name, ex.Message);
344	            }
345	        }
346	
347	        // ─────────────────────────────────────────────────────────────────────
348	        // Parse dd-MM-yyyy → yyyy-MM-dd for SP date params
349	        // ─────────────────────────────────────────────────────────────────────
350	        private static string ParseDateToYMD(string dateStr)
351	        {
352	            if (string.IsNullOrWhiteSpace(dateStr)) return "";
353	            try
354	            {
355	                return DateTime.ParseExact(dateStr.Trim(), "dd-MM-yyyy", null)
356	                               .ToString("yyyy-MM-dd");
357	            }
358	            catch
359	            {
360	                Logger.Warn("Could not parse date: {0}", dateStr);
361	                return dateStr;
362	            }
363	        }
364	
365	        // ─────────────────────────────────────────────────────────────────────
366	        // Send email with Excel attachment
367	        // ─────────────────────────────────────────────────────────────────────
368	        private static async Task SendEmailWithAttachment(string filePath)
369	        {
370	            try
371	            {
372	                Logger.Info("Sending email...");
373	
374	                using var mail = new MailMessage
375	                {
376	                    From = new MailAddress(_smtpSettings.FromEmail, _smtpSettings.Mail_header),
377	                    Subject = _smtpSettings.Subject.Replace("{Date}", DateTime.Now.ToString("dd-MM-yyyy")),
378	                    Body = _smtpSettings.Body,
379	                    IsBodyHtml = true
380	                };
381	
382	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
383	                    mail.To.Add(to.Trim());
384	
385	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
386	                    mail.CC.Add(cc.Trim());
387	
388	                using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
389	                {
390	                    var attachment = new Attachment(fs, Path.GetFileName(filePath));
391	                    mail.Attachments.Add(attachment);
392	
393	                    using (var smtp = new SmtpClient(_smtpSettings.Host, _smtpSettings.SmtpPort))
394	                    {
395	                        smtp.Credentials = new NetworkCredential(_smtpSettings.username, _smtpSettings.password);
396	                        smtp.EnableSsl = _smtpSettings.enableSsl;
397	                        await smtp.SendMailAsync(mail);
398	                    }
399	                }
400	
401	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
402	
403	                if (File.Exists(filePath))
404	                {
405	                    File.Delete(filePath);
406	                    Logger.Info("Deleted report: {0}", filePath);
407	                }
408	            }
409	            catch (Exception ex)
410	            {
411	                Logger.Error(ex, "Email send failed");
412	            }
413	        }
414	    }
415	}

