41	        // use different credentials without touching code.
42	        public class ServerInfo
43	        {
44	            public string Ip { get; set; }
45	            public string AdminUser { get; set; }
46	            public string AdminPassword { get; set; }
47	        }
48	
49	        public class RowPointers
50	        {
51	            public int ClientRow = 1;   // Sheet 1: OCR_AI ENABLED CLIENT LIST
52	            public int JobRow = 1;   // Sheet 2: OCR_AI TOTAL JOB COUNT
53	            public int FormatRow = 1;   // Sheet 3: OCR_AI Total Format details
54	        }
55	
56	        static async Task Main(string[] args)
57	        {
58	            bool isDryRun = args.Any(a => string.Equals(a, "--dry-run", StringComparison.OrdinalIgnoreCase));
59	
60	            try
61	            {
62	                RowPointers rows = new RowPointers();
63	
64	                var builder = new ConfigurationBuilder()
65	                    .SetBasePath(AppContext.BaseDirectory)
66	                    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);
67	
68	                IConfiguration config = builder.Build();
69	                _smtpSettings = config.GetSection("SmtpSettings").Get<SmtpSettings>();
70	                _serverDict = config.GetSection("server_ip_list").Get<Dictionary<string, ServerInfo>>();
71	                ReportFolder = config.GetSection("ReportSettings:ReportFolder").Value;
72	
73	                if (!Directory.Exists(ReportFolder))
74	                    Directory.CreateDirectory(ReportFolder);
75	
76	                using var workbook = new XLWorkbook();
77	                {
78	                    // ── Sheet 1: OCR_AI Enabled Client List ──────────────────
79	                    var wsClient = workbook.Worksheets.Add("OCR_AI ENABLED CLIENT LIST");
80	
81	                    // ── Sheet 2: OCR_AI Total Job Count ──────────────────────
82	                    var wsJob = workbook.Worksheets.Add("OCR_AI TOTAL JOB COUNT");
83	
84	                    // ── Sheet 3: OCR_AI Total Format Details ─────────────────
85	                    var wsFormat = workbook.Worksheets.Add("OCR_AI Total Format details");
86	
87	                    foreach (var kvp in _serverDict)
88	                    {
89	                        string serverName = kvp.Key;
90	                        ServerInfo serverInfo = kvp.Value;
91	
92	                        Logger.Info("Getting OCR data for server {0} ({1})", serverName, serverInfo.Ip);
93	
94	                        // Admin DB connection — credentials come from config per server
95	                        // (e.g. Local uses sa, live IPs use rtsadmin) so no code change is needed to switch.
96	                        string connString = $"Server={serverInfo.Ip};database=ADMIN_IMPEX;uid={serverInfo.AdminUser};pwd={serverInfo.AdminPassword};TrustServerCertificate=True;";
97	
98	                        await GetOcrDataList(connString, wsClient, wsJob, wsFormat, serverName, rows);
99	                    }
100	
101	                    // ── Style all three sheets ────────────────────────────────
102	                    StyleSheet(wsClient, "OCR AI ENABLED CLIENT LIST", rows.ClientRow - 1, 7);
103	                    StyleSheet(wsJob, "OCR AI TOTAL JOB COUNT", rows.JobRow - 1, -1); // dynamic cols
104	                    StyleSheet(wsFormat, "OCR AI TOTAL FORMAT DETAILS", rows.FormatRow - 1, 15);
105	
106	                    fileName = $"OCR_AI_Report_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
107	                    savePath = Path.Combine(ReportFolder, fileName);
108	                    workbook.SaveAs(savePath);
109	                    Logger.Info("Excel saved: {0}", savePath);
110	                }
111	
112	                if (isDryRun)
113	                {
114	                    Logger.Info("Dry run: skipping email send. Report left at {0} for inspection.", savePath);
115	                    return;
116	                }
117	
118	                await SendEmailWithAttachment(savePath);
119	
120	                if (File.Exists(savePath))
121	                {
122	                    File.Delete(savePath);
123	                    Logger.Info("Deleted report after email: {0}", fileName);
124	                }
125	            }
126	            catch (Exception ex)
127	            {
128	                Logger.Error(ex, "Error in Main");
129	            }
130	        }
