132	        // ─────────────────────────────────────────────────────────────────────
133	        // Main data fetch per server
134	        // ─────────────────────────────────────────────────────────────────────
135	        private static async Task GetOcrDataList(
136	            string connString,
137	            IXLWorksheet wsClient,
138	            IXLWorksheet wsJob,
139	            IXLWorksheet wsFormat,
140	            string serverName,
141	            RowPointers rows)
142	        {
143	            await Task.Run(() =>
144	            {
145	                // ── Step 1: Call admin SP to get enabled OCR companies ────────
146	                DataSet adminData;
147	                try
148	                {
149	                    adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
150	                }
151	                catch (Exception ex)
152	                {
153	                    Logger.Error(ex, "Admin SP call failed for server {0}", serverName);
154	                    return;
155	                }
156	
157	                if (adminData == null || adminData.Tables.Count < 2)
158	                {
159	                    Logger.Warn("Server {0}: No OCR data returned from admin SP", serverName);
160	                    return;
